    stdout_bytes = decode_base64_field(data["stdout"])
    stderr_bytes = decode_base64_field(data["stderr"])
    actual_code, actual_out, actual_err = execute(stdin_bytes)
    if (
        actual_code != exit_code
        or actual_out != stdout_bytes
